import {uid} from './ids.js?v=87ae808bfa10375d';
import {isScenery,sceneConfig,sceneCenterline,pathLength,validateScene} from './scenery-geometry.js?v=87ae808bfa10375d';
import {sceneryMarkup} from './scenery.js?v=87ae808bfa10375d';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class SceneryUI{
 constructor(api){this.api=api;this.draft=null;this.drag=null;this.hover=null;
  const svg=$('#canvas');
  svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false||this.space)return;const vertex=e.target.closest('[data-scene-vertex]');if(!this.draft&&!vertex)return;e.preventDefault();e.stopImmediatePropagation();svg.focus();const at=api.point(e);
   if(this.draft){const pts=this.draft.points;if(pts.length&&Math.hypot(at.x-pts.at(-1).x,at.y-pts.at(-1).y)<1)return;if(pts.length>=64)return api.toast('最多 64 个顶点');pts.push(at);if(this.draft.part.sceneType==='runway'&&pts.length===2)this.finish();else this.redraw();return;}
   const p=api.selection()[0];if(!p)return;this.drag={p,index:Number(vertex.dataset.sceneVertex),before:structuredClone(p.scene),pointerId:e.pointerId};svg.setPointerCapture(e.pointerId);
  },true);
  svg.addEventListener('pointermove',e=>{if(this.space)return;if(this.draft){this.hover=api.point(e);api.redraw();e.stopImmediatePropagation();}if(this.drag&&e.pointerId===this.drag.pointerId){e.stopImmediatePropagation();const {p,index}=this.drag,q=api.point(e),a=p.angle*Math.PI/180,dx=q.x-p.x,dy=q.y-p.y;p.scene.points[index]={x:dx*Math.cos(a)+dy*Math.sin(a),y:(-dx*Math.sin(a)+dy*Math.cos(a))*p.flip};api.redraw();}},true);
  svg.addEventListener('pointerup',e=>{if(!this.drag||e.pointerId!==this.drag.pointerId)return;e.stopImmediatePropagation();const d=this.drag,next=structuredClone(d.p.scene);d.p.scene=d.before;this.drag=null;try{const valid=validateScene(api.parts()[d.p.partId],{...d.p,scene:next});api.commit(()=>d.p.scene=valid.scene);}catch(error){api.toast(error.message);api.refresh();}if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);},true);
  for(const event of ['pointercancel','lostpointercapture'])svg.addEventListener(event,()=>this.cancelDrag(),true);
  window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#modal').open)return;if(e.code==='Space'){this.space=true;return;}if(this.drag&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();this.cancelDrag();return;}if(!this.draft)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();this.cancel();}else if(e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();this.finish();}else if(e.key==='Backspace'||e.key==='Delete'||(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.stopImmediatePropagation();this.draft.points.pop();this.redraw();}else if(!['h','H'].includes(e.key)){e.stopImmediatePropagation();}},true);
  window.addEventListener('keyup',e=>{if(e.code==='Space')this.space=false;});window.addEventListener('blur',()=>{this.space=false;this.cancelDrag();});
  $('#scene-finish').onclick=()=>this.finish();$('#scene-back').onclick=()=>{this.draft?.points.pop();this.redraw();};$('#scene-cancel').onclick=()=>this.cancel();
 }
 cancelDrag(){if(!this.drag)return;this.drag.p.scene=this.drag.before;this.drag=null;this.api.refresh();}
 cancel(){this.cancelDrag();this.draft=null;this.hover=null;this.redraw();}
 redraw(){const d=this.draft;$('#scene-draw-tools').hidden=!d;if(d){$('#scene-draw-status').textContent=`${d.part.label} · ${d.points.length} 个点`;$('#scene-finish').disabled=d.points.length<(d.part.sceneType==='apron'?3:2);}this.api.redraw();}
 start(part){this.cancel();this.draft={part,points:[],layerId:this.api.layer().id,z:this.api.layer().height};this.redraw();this.api.toast(part.sceneType==='runway'?'点击跑道两端，确定方向与长度':'连续点击绘制，Enter 或「完成」结束，Esc 取消');}
 finish(){const d=this.draft;if(!d)return;const min=d.part.sceneType==='apron'?3:2;if(d.points.length<min)return this.api.toast(`请至少绘制 ${min} 个点`);if(this.api.project().pieces.length>=5000)return this.api.toast('方案最多 5000 个零件');const start=d.points[0],pts=d.points.map(q=>({x:q.x-start.x,y:q.y-start.y})),p={id:uid(),partId:d.part.id,x:start.x,y:start.y,angle:0,flip:1,z:d.z,zEnd:d.z,layerId:d.layerId,scene:{...sceneConfig(d.part),points:pts}};
 if(d.part.sceneType==='runway'){delete p.scene.points;p.scene.length=Math.hypot(pts[1].x,pts[1].y);p.angle=Math.atan2(pts[1].y,pts[1].x)*180/Math.PI;}
 try{p.scene=validateScene(d.part,p).scene;}catch(e){return this.api.toast(e.message);}this.draft=null;this.hover=null;this.api.commit(project=>project.pieces.push(p));this.api.select(p.id);this.redraw();this.api.toast('已绘制，可拖动控制点或在右侧修改尺寸');
 }
 markup(unit){let out='';const d=this.draft;
 if(d){const pts=[...d.points,...(this.hover?[this.hover]:[])];if(pts.length>=2){const start=pts[0],p={id:'draft',x:start.x,y:start.y,angle:0,flip:1,scene:{...sceneConfig(d.part),points:pts.map(q=>({x:q.x-start.x,y:q.y-start.y}))}};if(d.part.sceneType==='runway'){delete p.scene.points;p.scene.length=Math.hypot(pts.at(-1).x-start.x,pts.at(-1).y-start.y);p.angle=Math.atan2(pts.at(-1).y-start.y,pts.at(-1).x-start.x)*180/Math.PI;}out+=`<g pointer-events="none">${sceneryMarkup(d.part,p,{ghost:true,exporting:true})}</g>`;}out+=d.points.map(q=>`<circle cx="${q.x}" cy="${q.y}" r="${4*unit}" fill="#fff" stroke="#338da0" pointer-events="none"/>`).join('');}
 const selected=this.api.selection();if(!d&&selected.length===1){const p=selected[0],part=this.api.parts()[p.partId];if(isScenery(part)&&p.scene?.points)out+=`<g transform="translate(${p.x} ${p.y}) rotate(${p.angle}) scale(1 ${p.flip})">${p.scene.points.map((q,i)=>`<circle data-scene-vertex="${i}" cx="${q.x}" cy="${q.y}" r="${5*unit}" fill="white" stroke="#21879d" stroke-width="${1.5*unit}" style="cursor:move"><title>拖动顶点 ${i+1} · Esc 取消</title></circle>`).join('')}</g>`;}
 return out;
 }
 inspector(p,part){const api=this.api,c=sceneConfig(part,p),air=part.kind==='aircraft',path=['road','taxiway'].includes(part.sceneType),runway=part.sceneType==='runway',custom=part.id==='AIR-200-CUSTOM';
 $('#selection-panel').innerHTML=`<div class="section-heading"><h2>${air?'飞机模型':'场景属性'}</h2><span class="badge">${api.selection().length>1?'已选 '+api.selection().length+' 个':'1:200'}</span></div><div class="part-title">${esc(c.label||part.label)}</div><p class="shape-note">${air?'飞机尺寸为模型毫米。默认按原型 1:200 换算，外形为自绘示意，可按实物调整。':'按模型毫米规划，可与轨道一起放置、移动和旋转。'}</p><label class="field">显示名称<input id="scene-label" maxlength="60" value="${esc(c.label||part.label)}"></label><div class="two-fields">${[['x','X / mm',p.x],['y','Y / mm',p.y],['angle','旋转 / °',p.angle],['z','底部高度 / mm',p.z||0]].map(([key,label,n])=>`<label>${label}<input id="prop-${key}" type="number" step="0.1" value="${n.toFixed(2)}"></label>`).join('')}${(!c.points?['length','width','height']:path?['width']:[]).map(k=>`<label>${{length:air?'机长':'长度',width:air?'翼展':'宽度',height:air?'总高':'建筑高度'}[k]} / mm<input id="scene-${k}" type="number" min="${k==='height'&&!air?0:1}" max="50000" step="0.1" value="${Number(c[k].toFixed(2))}"></label>`).join('')}</div><label class="field">${air?'机身配色':'材质配色'}<input id="scene-color" type="color" value="${c.color||'#317b91'}"></label>${part.sceneType==='road'?`<label class="field">车道数<input id="scene-lanes" type="number" min="1" max="8" value="${c.lanes}"></label>`:''}${path?`<label class="check-row"><input id="scene-curved" type="checkbox" ${c.curved?'checked':''}>圆滑转弯</label><p class="shape-note">道路中心线长 ${pathLength(sceneCenterline(part,p)).toFixed(1)} mm。${c.points?'拖动蓝色控制点调整走向。':''}</p>`:''}${runway?`<div class="two-fields"><label>跑道编号<input id="scene-runwayNumber" type="number" min="1" max="36" value="${c.runwayNumber}"></label><label>平行跑道<select id="scene-runwaySide">${[['','无'],['L','L 左'],['C','C 中'],['R','R 右']].map(([v,l])=>`<option value="${v}" ${c.runwaySide===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="shape-note">按 1:200 对应原型 ${(c.length/5).toFixed(0)} × ${(c.width/5).toFixed(0)} m。默认是展示型缩短跑道；3000 m 跑道需模型长度 15000 mm。编号由你指定，另一端自动相差 18。</p>`:''}${c.points?'<button id="scene-points" class="full-btn">编辑顶点坐标 ↗</button>':''}${air?`<p class="shape-note">${esc(part.notes.join(' '))}</p>${!custom?'<button id="scene-reset" class="full-btn">恢复该机型的 1:200 尺寸</button>':''}${part.source?`<a class="source-link" href="${esc(part.source)}" target="_blank" rel="noopener">查看原型尺寸来源 ↗</a>`:''}`:''}`;
 const set=(key,value)=>{try{const trial={...p,scene:{...c,[key]:value}};const valid=validateScene(part,trial);api.commit(()=>p.scene=valid.scene);}catch(e){api.toast(e.message);api.refresh();}};
 for(const k of ['length','width','height','lanes','runwayNumber','label','color','runwaySide','curved']){const el=$('#scene-'+k);if(el)el.onchange=()=>set(k,k==='curved'?el.checked:['label','color','runwaySide'].includes(k)?el.value:Number(el.value));}
 for(const k of ['x','y','angle','z'])$('#prop-'+k).onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||Math.abs(n)>(k==='z'?10000:k==='angle'?36000:100000)){api.toast('请输入有效坐标或高度');api.refresh();return;}api.commit(()=>{p[k]=n;if(k==='z')p.zEnd=n;});};
 if($('#scene-reset'))$('#scene-reset').onclick=()=>api.commit(()=>p.scene={...c,...part.dimensions});
 if($('#scene-points'))$('#scene-points').onclick=()=>{api.modal('编辑顶点坐标',`<p>相对于该零件原点，单位 mm；每行填写 X, Y。最多 64 个点。</p><textarea id="scene-coordinates" rows="10" style="width:100%">${c.points.map(q=>q.x.toFixed(1)+', '+q.y.toFixed(1)).join('\n')}</textarea><button id="scene-points-apply" class="full-btn primary">应用坐标</button>`);$('#scene-points-apply').onclick=()=>{const points=$('#scene-coordinates').value.trim().split('\n').map(row=>{const [x,y,...rest]=row.trim().split(/[,，\s]+/).map(Number);return {x:rest.length?NaN:x,y};});try{const valid=validateScene(part,{...p,scene:{...c,points}});api.commit(()=>p.scene=valid.scene);$('#modal').close();}catch(e){api.toast(e.message);}};};
 }
}
